import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { requesters, independentApprovers, MissingRequester } from "../src/independent-approval.js";

const fx = JSON.parse(readFileSync(new URL("./fixtures/agent-pr.json", import.meta.url), "utf8"));
const approved = (login: string, sha = fx.headSha, type = "User") =>
  ({ state: "APPROVED", commit_id: sha, user: { login, type } });

test("a human PR approved by a teammate passes", () => {
  const people = requesters({ user: { login: "sean" }, body: null }, ["sean"], []);
  assert.deepEqual(independentApprovers([approved("dana")], fx.headSha, people), new Set(["dana"]));
});
test("an agent PR approved only by its requester fails", () => {
  const people = requesters(fx.pr, [], []);
  assert.equal(independentApprovers([approved("sean")], fx.headSha, people).size, 0);
});
test("someone who edited the body then approves is not independent", () => {
  const people = requesters(fx.pr, [], ["dana"]);
  assert.equal(independentApprovers([approved("dana")], fx.headSha, people).size, 0);
});
test("an approval on an older commit fails", () => {
  const people = requesters(fx.pr, [], []);
  assert.equal(independentApprovers([approved("dana", "aaa")], fx.headSha, people).size, 0);
});
test("a bot approval is ignored", () => {
  const people = requesters(fx.pr, [], []);
  assert.equal(independentApprovers([approved("some-app[bot]", fx.headSha, "Bot")], fx.headSha, people).size, 0);
});
test("an agent PR without a Requested-by line fails closed", () => {
  assert.throws(() => requesters({ user: { login: "rhino-ai-agents[bot]" }, body: "no line" }, [], []), MissingRequester);
});
